/* prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * It validates a Roman numeral (case‑insensitive) and prints its
 * integer value, or "INVALID" if the input is not a canonical Roman
 * numeral.
 *
 * The program accepts exactly one argument.  Empty strings, strings
 * longer than 63 characters, characters outside I V X L C D M and
 * non‑canonical forms are rejected.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* Table of Roman symbols in descending order together with their
 * integer values.  The order is the canonical one used for both
 * parsing and generation. */
static const struct {
    const char *sym;
    int value;
} roman_table[] = {
    {"M",  1000},
    {"CM",  900},
    {"D",   500},
    {"CD",  400},
    {"C",   100},
    {"XC",   90},
    {"L",    50},
    {"XL",   40},
    {"X",    10},
    {"IX",    9},
    {"V",     5},
    {"IV",    4},
    {"I",     1}
};

#define ROMAN_TABLE_SIZE (sizeof roman_table / sizeof roman_table[0])
#define MAX_INPUT_LEN   63          /* same limit as the original binary */
#define MAX_ROMAN_VALUE 3999        /* highest value representable with the table */

/* Convert a string to upper case, storing the result in `out`.
 * `out` must have room for at least strlen(in)+1 bytes. */
static void to_upper(const char *in, char *out)
{
    while (*in) {
        *out++ = (char)toupper((unsigned char)*in);
    }
    *out = '\0';
}

/* Return 1 if `c` is a valid Roman numeral character, 0 otherwise. */
static int is_roman_char(char c)
{
    return c == 'I' || c == 'V' || c == 'X' ||
           c == 'L' || c == 'C' || c == 'D' || c == 'M';
}

/* Parse `s` (which must already be upper‑case) and compute its integer
 * value while simultaneously checking that the representation is
 * canonical.  Returns the value on success, or -1 on failure. */
static int parse_roman(const char *s)
{
    int total = 0;
    size_t i = 0;               /* position in the input string */

    while (s[i] != '\0') {
        int matched = 0;
        for (size_t t = 0; t < ROMAN_TABLE_SIZE; ++t) {
            const char *sym = roman_table[t].sym;
            size_t len = strlen(sym);
            if (strncmp(s + i, sym, len) == 0) {
                total += roman_table[t].value;
                i += len;
                matched = 1;
                break;          /* longest possible match is taken first */
            }
        }
        if (!matched)          /* no table entry matches the current prefix */
            return -1;
    }

    if (total <= 0 || total > MAX_ROMAN_VALUE)
        return -1;

    return total;
}

/* Produce the canonical Roman representation of `value` (1 ≤ value ≤ 3999)
 * and store it in `out`.  `out` must be large enough (the longest
 * possible numeral is "MMMDCCCLXXXVIII", 15 characters). */
static void generate_roman(int value, char *out)
{
    out[0] = '\0';
    for (size_t t = 0; t < ROMAN_TABLE_SIZE; ++t) {
        while (value >= roman_table[t].value) {
            strcat(out, roman_table[t].sym);
            value -= roman_table[t].value;
        }
    }
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    if (len == 0 || len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* Convert to upper case and verify characters */
    char upper[MAX_INPUT_LEN + 1];
    to_upper(input, upper);

    for (size_t i = 0; i < len; ++i) {
        if (!is_roman_char(upper[i])) {
            puts("INVALID");
            return 0;
        }
    }

    /* Parse and obtain the integer value */
    int value = parse_roman(upper);
    if (value == -1) {
        puts("INVALID");
        return 0;
    }

    /* Re‑create the canonical representation and compare */
    char canonical[32];               /* more than enough */
    generate_roman(value, canonical);

    if (strcmp(upper, canonical) != 0) {
        puts("INVALID");
        return 0;
    }

    printf("%d\n", value);
    return 0;
}
